#include <iostream>
#include <stdexcept>

double grams_from(int milligrams) {
    if (milligrams < 0) throw std::runtime_error("device failed");
    return milligrams / 1000.0; // A double divisor keeps the fraction.
}
int main() {
    std::cout << "grams=" << grams_from(1250) << '\n';
    try { std::cout << grams_from(-1) << '\n'; }
    catch (const std::runtime_error&) { std::cout << "reading rejected\n"; }
}

#include <iostream>

double bad_grams(int raw) {
    return static_cast<double>(raw / 1000); // The fraction is already lost.
}
int main() {
    const int measured = 1999;
    const int failed = -1;
    std::cout << "lost=" << bad_grams(measured) << '\n';
    std::cout << "preserved=" << measured / 1000.0 << '\n';
    // This deliberately wrong rule confuses failure with weight.
    std::cout << std::boolalpha << "failure accepted="
              << (failed / 1000.0 <= 2.0) << '\n';
}
